class Batch:
    """One 10,000-cover batch in a one-million-cover archive.org item."""

    def __init__(self, item_id, batch_id, size=None):
        self.item_id, self.batch_id = self._normalize_ids(item_id, batch_id)
        self.size = _size(size) if size is not None else None

    @staticmethod
    def _normalize_ids(item_id, batch_id):
        item = _decimal_id(item_id, 9999, 'item ID')
        batch = _decimal_id(batch_id, 99, 'batch ID')
        return f'{item:04d}', f'{batch:02d}'

    def _norm_ids(self):
        return self.item_id, self.batch_id

    @property
    def start_id(self):
        return int(self.item_id) * IMAGES_PER_ITEM + int(self.batch_id) * IMAGES_PER_BATCH

    @classmethod
    def get_relpath(cls, item_id, batch_id, size='', ext='zip'):
        item, batch = cls._normalize_ids(item_id, batch_id)
        _size(size)
        _extension(ext)
        stem = f'{size + "_" if size else ""}covers_{item}'
        return os.path.join('items', stem, f'{stem}_{batch}.{ext}')

    @classmethod
    def get_abspath(cls, item_id, batch_id, size='', ext='zip'):
        return os.path.join(config.data_root, cls.get_relpath(item_id, batch_id, size, ext))

    def item_name(self, size=''):
        _size(size)
        return f'{size + "_" if size else ""}covers_{self.item_id}'

    def zip_filename(self, size=''):
        return os.path.basename(self.get_relpath(self.item_id, self.batch_id, size))

    @contextmanager
    def locked(self):
        """A shared-filesystem, nonblocking lock for this 10k ID range."""
        lockdir = os.path.join(config.data_root, 'items', '.locks')
        os.makedirs(lockdir, exist_ok=True)
        lockpath = os.path.join(lockdir, f'covers_{self.item_id}_{self.batch_id}.lock')
        with open(lockpath, 'a+b') as lock:
            try:
                fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError as exc:
                raise BatchBusyError(f'batch {self.item_id}_{self.batch_id} is busy') from exc
            try:
                yield
            finally:
                fcntl.flock(lock, fcntl.LOCK_UN)

    def _finalize_locked(self, uploader, test):
        self._assert_ready()
        missing = [
            self.zip_filename(size) for size in SIZES
            if not uploader.is_uploaded(self.item_name(size), self.zip_filename(size))
        ]
        if missing:
            raise UploadIncompleteError(f'upload incomplete: {", ".join(missing)}')
        if test:
            return 0
        originals = CoverDB.update_completed_batch(self.item_id, self.batch_id)
        for cover in originals:
