        for size in SIZES:
            path = self.get_abspath(self.item_id, self.batch_id, size)
            with suppress(FileNotFoundError):
                os.remove(path)
        return len(originals)

    def _assert_ready(self):
        """Require a closed range and a local zip entry for each staged row."""
        cover_db = CoverDB()
        rows = list(cover_db.get_archived_in_batch(self.item_id, self.batch_id))
        pending = [
            Cover(row) for row in rows
            if not row.get('uploaded') or any(
                row.get(f'filename_{size}' if size else 'filename')
                != Cover.get_cover_url(row.id, size)
                for size in SIZES
