            raise UploadIncompleteError(f'batch {self.item_id}_{self.batch_id} is still open')
        if list(cover_db.get_unarchived_in_batch(self.item_id, self.batch_id)):
            raise UploadIncompleteError(f'batch {self.item_id}_{self.batch_id} has unstaged covers')
