    def finalize(self, start_id=None, test=True, uploader=None):
        if start_id is not None and int(start_id) != self.start_id:
            raise ValueError('start_id does not match this batch')
        with self.locked():
            return self._finalize_locked(uploader or Uploader, test)

    def process_pending(self, upload=False, finalize=False, test=True, uploader=None):
        """Validate local zips, optionally upload and reconcile this batch.

        Raises UploadIncompleteError if finalization was requested before every
        size is present remotely. A retry skips files already found remotely.
        """
        uploader = uploader or Uploader
        statuses = {}
        with self.locked():
            if upload:
                self._assert_ready()
            for size in SIZES if self.size is None else (self.size,):
                path = self.get_abspath(self.item_id, self.batch_id, size)
                item, filename = self.item_name(size), self.zip_filename(size)
                local = os.path.isfile(path)
