                    with zipfile.ZipFile(path) as archive_file:
                        if archive_file.testzip() is not None:
                            raise zipfile.BadZipFile(f'corrupt zip: {path}')
                remote = uploader.is_uploaded(item, filename)
                if upload and local and not remote and not test:
                    uploader.upload(item, [path])
                    remote = uploader.is_uploaded(item, filename)
                statuses[size] = {'local': local, 'uploaded': remote}
            if finalize:
                statuses['completed'] = self._finalize_locked(uploader, test)
        return statuses


